# ===================================================================== units.py
from __future__ import annotations
from dataclasses import dataclass
from enum import IntEnum
from typing import NewType

NetUid = NewType("NetUid", int)
Block = NewType("Block", int)
Rao = NewType("Rao", int)              # TAO, 1e-9
AlphaRao = NewType("AlphaRao", int)    # alpha of ONE subnet generation, 1e-9
PriceRao = NewType("PriceRao", int)    # rao TAO per 1 alpha (spot*1e9): the chain's limit_price unit
Ppm = NewType("Ppm", int)              # parts per million: weights, fractions, slippage budgets
Hotkey = NewType("Hotkey", str)        # ss58
StrategyId = NewType("StrategyId", str)
OrderId = NewType("OrderId", str)      # deterministic digest, never random
RAO = 10**9
PPM = 1_000_000

@dataclass(frozen=True, slots=True, order=True)
class SubnetKey:
    """Asset identity = (netuid, NetworkRegisteredAt). netuids are reused ~weekly; never key by netuid alone."""
    netuid: NetUid
    reg_block: Block

@dataclass(frozen=True, slots=True, order=True)
class PositionKey:
    subnet: SubnetKey
    hotkey: Hotkey

class Phase(IntEnum):
    """Intra-block ordering used by every mode. The snapshot batch (INGEST..EMIT) commits first; fills due at this block land after it."""
    INGEST = 0; ACCOUNT = 1; DECIDE = 2; EMIT = 3; VENUE = 4

@dataclass(frozen=True, slots=True, order=True)
class LogicalTime:
    """Chain time only. No wall clock ever enters the engine."""
    block: Block
    phase: Phase = Phase.INGEST
    sub: int = 0

# ===================================================================== amm.py  (integer rao in/out; fractional powers via Decimal)
from dataclasses import replace
from decimal import ROUND_FLOOR, Context, Decimal
_C = Context(prec=60, rounding=ROUND_FLOOR)
FEE_DEN, E18 = 65_535, 10**18
MIN_RESERVE, MAX_IN_MULT, MIN_STAKE = 1_000_000, 1_000, 2_000_000     # read live on the chain; never trust constants

class SwapError(Exception):
    def __init__(self, code: str) -> None:            # code == the chain error name (SlippageTooHigh, AmountTooLow, ...)
        super().__init__(code); self.code = code

class PoolKind(IntEnum):
    CP_REAL = 1        # Era A: constant product on (SubnetTAO, SubnetAlphaIn)
    CP_V3_VIRTUAL = 2  # Era B: constant product on virtual reserves L*sqrtP, L/sqrtP
    BALANCER = 3       # Era C: weights from Swap.SwapBalancer (~0.5/0.5; never hard-code)

@dataclass(frozen=True, slots=True)
class SwapQuote:
    amount_in: int; fee: int; amount_out: int
    author_fee_tao: int      # sells only: TAO paid out to the block author for the fee alpha
    d_tao: int; d_alpha: int # change of BOTH real and pricing reserves (feeds the own-impact overlay)
    shortfall_ppm: int       # 1 - executed/spot (incl. swap fee)

@dataclass(frozen=True, slots=True)
class PoolState:
    kind: PoolKind
    tao: Rao; alpha: AlphaRao        # real SubnetTAO / SubnetAlphaIn: caps, sizing, depth
    px_tao: int; px_alpha: int       # pricing-model reserves (== real except CP_V3_VIRTUAL)
    w_quote_e18: int                 # Perquintill raw (TAO weight * 1e18); 5*10**17 for CP kinds
    fee_rate: int                    # /65535 (33 => 0.0504%)
    @staticmethod
    def balancer(tao: int, alpha: int, w_quote_e18: int = E18 // 2, fee_rate: int = 33) -> PoolState:
        return PoolState(PoolKind.BALANCER, Rao(tao), AlphaRao(alpha), tao, alpha, w_quote_e18, fee_rate)
    @property
    def w_base_e18(self) -> int: return E18 - self.w_quote_e18
    def spot(self) -> Decimal:       # TAO per alpha = (w_base/w_quote) * y/x
        return _C.divide(_C.multiply(self.w_base_e18, self.px_tao), _C.multiply(self.w_quote_e18, self.px_alpha))
    def spot_rao(self) -> PriceRao: return PriceRao(int(_C.multiply(self.spot(), RAO)))
    def shifted(self, d_tao: int, d_alpha: int) -> PoolState:     # own-impact overlay / post-trade pool
        return replace(self, tao=Rao(self.tao + d_tao), alpha=AlphaRao(self.alpha + d_alpha),
                       px_tao=self.px_tao + d_tao, px_alpha=self.px_alpha + d_alpha)

def _out_given_in(r_in: int, r_out: int, d: int, w_in: int, w_out: int) -> int:
    if w_in == w_out: return r_out * d // (r_in + d)                       # exact integer math at 0.5/0.5
    frac = _C.power(_C.divide(r_in, r_in + d), _C.divide(w_in, w_out))
    return int(_C.multiply(r_out, _C.subtract(1, frac)))

def quote_buy(p: PoolState, tao_in: int) -> SwapQuote:
    fee = tao_in * p.fee_rate // FEE_DEN; dy = tao_in - fee
    if tao_in < MIN_STAKE + fee or dy < MIN_STAKE: raise SwapError("AmountTooLow")
    if tao_in > MAX_IN_MULT * p.tao: raise SwapError("InsufficientLiquidity")
    if p.alpha < MIN_RESERVE: raise SwapError("ReservesTooLow")
    out = _out_given_in(p.px_tao, p.px_alpha, dy, p.w_quote_e18, p.w_base_e18)
    if out <= 0 or out > p.px_alpha: raise SwapError("InsufficientLiquidity")
    return SwapQuote(tao_in, fee, out, 0, dy, -out, _shortfall_ppm(p.spot(), tao_in, out, True))

def quote_sell(p: PoolState, alpha_in: int, *, partial_remaining: bool = False) -> SwapQuote:
    fee_a = alpha_in * p.fee_rate // FEE_DEN; dx = alpha_in - fee_a
    if alpha_in > MAX_IN_MULT * p.alpha: raise SwapError("InsufficientLiquidity")
    if p.tao < MIN_RESERVE: raise SwapError("ReservesTooLow")
    x, y = p.px_alpha, p.px_tao
    out = _out_given_in(x, y, dx, p.w_base_e18, p.w_quote_e18)
    if out <= 0 or out > y: raise SwapError("InsufficientLiquidity")
    if partial_remaining and out < MIN_STAKE: raise SwapError("AmountTooLow")
    x1, y1 = x + dx, y - out                                             # fee alpha is sold fee-free into the same pool
    tao_fee = _out_given_in(x1, y1, fee_a, p.w_base_e18, p.w_quote_e18) if fee_a else 0
    return SwapQuote(alpha_in, fee_a, out, tao_fee, -(out + tao_fee), alpha_in, _shortfall_ppm(p.spot(), alpha_in, out, False))

def _shortfall_ppm(spot: Decimal, in_amt: int, out_amt: int, buy: bool) -> int:
    ideal = _C.divide(in_amt, spot) if buy else _C.multiply(in_amt, spot)
    return 0 if ideal <= 0 else int(_C.multiply(_C.subtract(1, _C.divide(out_amt, ideal)), PPM))

def max_buy_to_limit(p: PoolState, limit: PriceRao) -> int:
    """Largest gross TAO whose post-fill MARGINAL price stays <= limit (add_stake_limit semantics; strict: limit<=spot raises)."""
    s, lim = p.spot(), _C.divide(limit, RAO)
    if lim <= s: raise SwapError("PriceLimitExceeded")
    net = int(_C.multiply(p.px_tao, _C.subtract(_C.power(_C.divide(lim, s), _C.divide(p.w_base_e18, E18)), 1)))
    return net * FEE_DEN // (FEE_DEN - p.fee_rate)

def max_sell_to_limit(p: PoolState, limit: PriceRao) -> int:
    s, lim = p.spot(), _C.divide(limit, RAO)
    if lim >= s: raise SwapError("PriceLimitExceeded")
    net = int(_C.multiply(p.px_alpha, _C.subtract(_C.power(_C.divide(s, lim), _C.divide(p.w_quote_e18, E18)), 1)))
    return net * FEE_DEN // (FEE_DEN - p.fee_rate)

def max_position_for_exit_slippage(p: PoolState, slip: Ppm) -> Rao:
    return Rao(p.tao * slip // (PPM - slip))                             # V_max = T*s/(1-s)

# ===================================================================== state.py
from enum import IntFlag

class Quality(IntFlag):
    OK = 0; TA_PRICE_MISMEASURED = 1; BALANCER_MIGRATION = 2; EARLY_DTAO_TINY_POOL = 4
    CHAIN_STALL_GAP = 8; DEFAULT_FILLED = 16; REFINED = 32; NOT_STARTED = 64

@dataclass(frozen=True, slots=True)
class HotkeyPool:
    """value(shares) = shares * total_alpha / total_shares. Yield raises total_alpha only; OUR share count never changes."""
    hotkey: Hotkey; total_alpha: AlphaRao
    total_shares: Decimal            # U64F64 (V1) or SafeFloat m*10^e (V2), decoded EXACTLY
    take_u16: int = 11_796           # Delegates[h]; never-set hotkeys default to 18%
    earns: bool = True               # key present in AlphaDividendsPerSubnet(n, .)
    def value_of(self, shares: Decimal) -> AlphaRao:
        if self.total_shares == 0: return AlphaRao(int(shares))
        return AlphaRao(int(_C.divide(_C.multiply(shares, self.total_alpha), self.total_shares)))
    def shares_for(self, alpha: int) -> Decimal:
        if self.total_alpha == 0 or self.total_shares == 0: return Decimal(alpha)
        return _C.divide(_C.multiply(alpha, self.total_shares), self.total_alpha)

@dataclass(frozen=True, slots=True)
class SubnetState:
    key: SubnetKey; pool: PoolState
    alpha_out: AlphaRao; protocol_alpha: AlphaRao
    moving_price: Decimal            # SubnetMovingPrice (I96F32, exact): emission share AND prune rank
    root_prop: Decimal; miner_burned: Decimal
    emission_enabled: bool; subtoken_enabled: bool
    first_emission_block: Block | None      # None => start_call never made
    last_epoch_block: Block; tempo: int
    hotkeys: tuple[HotkeyPool, ...] = ()
    escrow_alpha: AlphaRao | None = None    # validator-basket escrow E (post v441)
    quality: Quality = Quality.OK
    def hotkey(self, hk: Hotkey) -> HotkeyPool | None:
        return next((h for h in self.hotkeys if h.hotkey == hk), None)

@dataclass(frozen=True, slots=True)
class GlobalState:
    spec_version: int; subnet_limit: int; immunity_period: int; network_rate_limit: int
    last_registration_block: Block; registration_cost: int
    moving_alpha: Decimal; gate_bar: Decimal; gate_rank: int
    safe_mode_until: Block | None
    runtime_prune_target: NetUid | None = None     # get_subnet_to_prune() cross-check (live feeds only)

@dataclass(frozen=True, slots=True)
class ChainSnapshot:
    block: Block; block_hash: str; timestamp_ms: int
    glob: GlobalState
    subnets: tuple[SubnetState, ...]               # sorted by netuid; ONE generation per netuid per block
    _idx: dict[NetUid, SubnetState] = field(default_factory=dict, init=False, repr=False, compare=False, metadata={"codec": False})
    def __post_init__(self) -> None: object.__setattr__(self, "_idx", {s.key.netuid: s for s in self.subnets})
    def by_netuid(self, n: NetUid) -> SubnetState | None: return self._idx.get(n)
    def get(self, key: SubnetKey) -> SubnetState | None:
        s = self._idx.get(key.netuid)             # None if gone OR the netuid now holds a different generation (our asset was pruned)
        return s if s is not None and s.key == key else None
    def digest(self) -> str: return digest(self)   # stored in the lake; recomputed only by verify tools

# ===================================================================== orders.py
import hashlib
from enum import Enum
Attribution = tuple[tuple[StrategyId, Ppm], ...]          # parts-per-million split across originating strategies

class Side(str, Enum): BUY = "BUY"; SELL = "SELL"
class Urgency(IntEnum): LOW = 0; NORMAL = 1; HIGH = 2; CRITICAL = 3   # CRITICAL: prune imminent -> widen limit, may part-fill

class OrderState(str, Enum):
    INTENDED = "INTENDED"        # journaled, nothing sent (the outbox)
    SUBMITTING = "SUBMITTING"    # SubmitStarted journaled BEFORE any I/O
    SUBMITTED = "SUBMITTED"      # venue acked; in flight
    UNKNOWN = "UNKNOWN"          # I/O raised / crashed mid-submit: resolve from chain truth, NEVER blind-resend
    FILLED = "FILLED"; FAILED = "FAILED"; EXPIRED = "EXPIRED"; CANCELLED = "CANCELLED"     # terminal

TERMINAL = frozenset({OrderState.FILLED, OrderState.FAILED, OrderState.EXPIRED, OrderState.CANCELLED})
_NEXT = {OrderState.INTENDED: {OrderState.SUBMITTING, OrderState.CANCELLED},
         OrderState.SUBMITTING: {OrderState.SUBMITTED, OrderState.FAILED, OrderState.UNKNOWN},
         OrderState.UNKNOWN: {OrderState.SUBMITTED, OrderState.FILLED, OrderState.FAILED, OrderState.EXPIRED},
         OrderState.SUBMITTED: {OrderState.FILLED, OrderState.FAILED, OrderState.EXPIRED}}

class IllegalTransition(Exception): ...

def make_order_id(run_id: str, block: Block, key: SubnetKey, hotkey: Hotkey, side: Side, attempt: int) -> OrderId:
    raw = f"{run_id}|{block}|{key.netuid}|{key.reg_block}|{hotkey}|{side.value}|{attempt}".encode()
    return OrderId(hashlib.blake2b(raw, digest_size=12).hexdigest())

@dataclass(frozen=True, slots=True)
class OrderIntent:
    order_id: OrderId; attempt: int; created: Block
    key: SubnetKey; hotkey: Hotkey; side: Side
    tao_in: Rao                 # BUY: gross TAO to spend (0 for SELL)
    shares: Decimal             # SELL: hotkey-pool shares (exact; shares change only via OUR fills)
    sell_all: bool              # whole live position (exempt from partial-sell / dust minimums)
    limit_price: PriceRao       # bound on the pool's MARGINAL spot after the fill
    allow_partial: bool
    valid_until: Block          # last block inclusion is acceptable (shield era = 8 blocks)
    expected_out: int           # model expectation, for shortfall accounting
    urgency: Urgency; attribution: Attribution; reason: str
    def __post_init__(self) -> None:
        if self.side is Side.BUY and (self.tao_in <= 0 or self.shares != 0): raise ValueError("BUY needs tao_in>0, shares==0")
        if self.side is Side.SELL and (self.tao_in != 0 or self.shares <= 0): raise ValueError("SELL needs shares>0, tao_in==0")

@dataclass(frozen=True, slots=True)
class Fill:
    fill_id: str                # f"{order_id}:{attempt}:{leg}": the idempotency key of the accounting effect
    order_id: OrderId; attempt: int; block: Block
    key: SubnetKey; hotkey: Hotkey; side: Side
    tao: Rao                    # BUY: gross TAO spent (incl. swap fee). SELL: TAO received
    alpha: AlphaRao             # BUY: alpha received. SELL: alpha sold (the pool absorbs all of it)
    shares: Decimal
    swap_fee: int               # input-side units (TAO for BUY, alpha for SELL)
    author_fee_tao: Rao         # SELL: TAO paid out of the pool to the block author
    tx_fee: Rao                 # carrier + inner extrinsic fee paid by the delegate
    d_pool_tao: int; d_pool_alpha: int       # own-impact overlay input
    shortfall_ppm: int
    complete: bool              # False: allow_partial stopped at the limit

@dataclass(frozen=True, slots=True)
class OrderRecord:
    intent: OrderIntent
    state: OrderState = OrderState.INTENDED
    fill_ids: tuple[str, ...] = ()
    def to(self, new: OrderState) -> OrderRecord:
        if new not in _NEXT.get(self.state, set()): raise IllegalTransition(f"{self.intent.order_id}: {self.state.value} -> {new.value}")
        return replace(self, state=new)

# ===================================================================== signals.py  (declarative layer)
class SignalKind(str, Enum): TARGET = "TARGET"; EXIT = "EXIT"; AVOID = "AVOID"

@dataclass(frozen=True, slots=True)
class Signal:
    strategy: StrategyId; key: SubnetKey; asof: Block; kind: SignalKind
    weight_ppm: Ppm = Ppm(0)            # fraction of the STRATEGY SLEEVE (quantised here: no floats past this point)
    horizon_blocks: int = 0             # thesis validity / time stop; 0 = until next evaluation
    urgency: Urgency = Urgency.NORMAL
    hotkey: Hotkey | None = None        # None => planner picks the best earning hotkey
    reasons: tuple[str, ...] = ()       # machine-readable reason codes

@dataclass(frozen=True, slots=True)
class TargetPosition:
    key: SubnetKey; hotkey: Hotkey
    weight_ppm: Ppm                     # fraction of TOTAL NAV after allocation
    urgency: Urgency; max_exit_slippage_ppm: Ppm
    attribution: Attribution; reasons: tuple[str, ...] = ()

@dataclass(frozen=True, slots=True)
class TargetWeights:
    asof: Block
    items: tuple[TargetPosition, ...]   # sorted by key => canonical
    def get(self, key: SubnetKey) -> TargetPosition | None: return next((t for t in self.items if t.key == key), None)
    def reduced(self, key: SubnetKey, weight: Ppm, reason: str, urgency: Urgency | None = None) -> TargetWeights:
        out = []
        for t in self.items:
            if t.key == key:
                if weight > t.weight_ppm: raise ValueError("risk overlay tried to increase a target")     # monotone by construction
                t = replace(t, weight_ppm=weight, reasons=t.reasons + (reason,), urgency=urgency if urgency is not None else t.urgency)
            out.append(t)
        return TargetWeights(self.asof, tuple(out))

@dataclass(frozen=True, slots=True)
class RiskAction: overlay: str; key: SubnetKey | None; action: str; detail: str   # CLAMP|FORCE_EXIT|VETO_ENTRY|HALT_ENTRIES|HALT_ALL

@dataclass(frozen=True, slots=True)
class RiskDecision:
    targets: TargetWeights
    actions: tuple[RiskAction, ...] = ()
    halt_entries: bool = False          # exits stay allowed
    halt_all: bool = False              # nothing is sent (SafeMode, stale data)

# ===================================================================== portfolio.py  (typed state + independent double-entry ledger)
TAO = "TAO"
def alpha_unit(key: SubnetKey) -> str: return f"A:{key.netuid}:{key.reg_block}"

@dataclass(frozen=True, slots=True)
class Position:
    key: SubnetKey; hotkey: Hotkey
    shares: Decimal             # the real holding; yield raises the INDEX, never the share count
    cost_tao: Rao               # remaining cost basis incl. swap + tx fees
    opened_block: Block; attribution: Attribution
    @property
    def pkey(self) -> PositionKey: return PositionKey(self.key, self.hotkey)

@dataclass(frozen=True, slots=True)
class Portfolio:
    cash: Rao                   # free TAO on the DEDICATED coldkey
    fee_float: Rao              # TAO on the delegate that pays extrinsic fees (alpha-fee trap: never let it reach 0)
    positions: tuple[Position, ...] = ()        # sorted by PositionKey => canonical
    def get(self, pk: PositionKey) -> Position | None: return next((p for p in self.positions if p.pkey == pk), None)

@dataclass(frozen=True, slots=True)
class Posting: account: str; unit: str; amount: int

@dataclass(frozen=True, slots=True)
class LedgerTxn:
    txn_id: str; block: Block; postings: tuple[Posting, ...]
    def validate(self) -> None:                  # every unit (TAO, each alpha generation) must sum to zero
        sums: dict[str, int] = {}
        for p in self.postings: sums[p.unit] = sums.get(p.unit, 0) + p.amount
        if any(sums.values()): raise ValueError(f"unbalanced ledger txn {self.txn_id}: {sums}")

def fill_txn(f: Fill) -> LedgerTxn:
    mkt, au = f"market:{f.key.netuid}:{f.key.reg_block}", alpha_unit(f.key)
    pa = f"pos:{f.key.netuid}:{f.key.reg_block}:{f.hotkey}"
    if f.side is Side.BUY:
        p = [Posting("cash", TAO, -f.tao), Posting(mkt, TAO, f.tao - f.swap_fee), Posting("fees:swap", TAO, f.swap_fee),
             Posting(pa, au, f.alpha), Posting(mkt, au, -f.alpha)]
    else:
        p = [Posting(mkt, TAO, -(f.tao + f.author_fee_tao)), Posting("cash", TAO, f.tao), Posting("fees:swap", TAO, f.author_fee_tao),
             Posting(pa, au, -f.alpha), Posting(mkt, au, f.alpha)]
    if f.tx_fee: p += [Posting("fee_float", TAO, -f.tx_fee), Posting("fees:tx", TAO, f.tx_fee)]
    return LedgerTxn(f"fill:{f.fill_id}", f.block, tuple(p))
# check_invariants(portfolio, ledger, snapshot): cash/fee_float equal the ledger, never negative, and every position's
# index-value equals its ledger alpha balance within 2 rao. Two independent accumulations must agree after EVERY commit.

# ===================================================================== events.py  (closed, versioned vocabulary)
from typing import Callable, ClassVar, TypeVar
REGISTRY: dict[str, type] = {}
T = TypeVar("T", bound=type)

class Event:
    __slots__ = ()
    KIND: ClassVar[str]
    def idem(self) -> str | None: return None      # journal-level UNIQUE idempotency key

def event(kind: str) -> Callable[[T], T]:
    def deco(cls: T) -> T:
        setattr(cls, "KIND", kind); assert kind not in REGISTRY; REGISTRY[kind] = cls; return cls
    return deco

# --- inputs from the world (SnapshotObserved is a REFERENCE: payload lives in the lake, the digest pins its exact content)
@event("snapshot_observed")        @dataclass(frozen=True, slots=True)
class SnapshotObserved(Event):
    block: Block; block_hash: str; digest: str; ts_ms: int
    def idem(self) -> str: return f"snap:{self.block_hash}"
# --- derived chain facts: a pure diff of consecutive snapshots (the SAME function in every mode)
@event("subnet_registered")        @dataclass(frozen=True, slots=True)
class SubnetRegistered(Event): key: SubnetKey; block: Block
@event("subnet_removed")           @dataclass(frozen=True, slots=True)
class SubnetRemoved(Event): key: SubnetKey; last_seen: Block; kind: RemovalKind   # PRUNED | DISSOLVED | REPLACED
