class EmissionEnabledChanged(Event): key: SubnetKey; enabled: bool; block: Block
@event("epoch_drained")            @dataclass(frozen=True, slots=True)
class EpochDrained(Event): key: SubnetKey; epoch_block: Block
@event("spec_version_changed")     @dataclass(frozen=True, slots=True)
class SpecVersionChanged(Event): old: int; new: int; block: Block
# --- execution-side facts
