# ===================================================================== protocols.py  (the seams)
from typing import AsyncIterator, Protocol, Sequence, runtime_checkable

class SnapshotStore(Protocol):
    """Immutable decoded snapshots (Parquet lake + live hot buffer). NEVER returns data after the engine clock."""
    def get(self, block: Block) -> ChainSnapshot: ...
    def window(self, key: SubnetKey, until: Block, n: int) -> Sequence[ChainSnapshot]: ...      # raises LookaheadError if until > now

@dataclass(frozen=True, slots=True)
class SourceItem: time: LogicalTime; snapshot: ChainSnapshot

class DataSource(Protocol):
    """HistoricalSource (lake), LiveChainFeed (finalized heads) and JournalSource (recovery) all implement this."""
    store: SnapshotStore
    def stream(self, after: Block | None) -> AsyncIterator[SourceItem]: ...      # resume strictly after the last journaled snapshot

class VenueKind(str, Enum): SIM = "SIM"; PAPER = "PAPER"; LIVE = "LIVE"

@dataclass(frozen=True, slots=True)
class VenueCaps: kind: VenueKind; min_stake_rao: int; shield_latency_blocks: int; era_blocks: int; supports_move_stake: bool

class Resolution(str, Enum):
    NOT_PLACED = "NOT_PLACED"    # provably never reached the chain (era expired, nonce unconsumed): safe to re-decide
    PLACED = "PLACED"; LANDED = "LANDED"; UNRESOLVABLE_YET = "UNRESOLVABLE_YET"

class ExecutionVenue(Protocol):
    """Venues hold NO hidden state: whatever they need after a restart is rebuilt from journaled events via observe()."""
    caps: VenueCaps
    async def submit(self, intent: OrderIntent, now: Block) -> Event: ...        # idempotent on (order_id, attempt); raising => UNKNOWN
    async def advance(self, snap: ChainSnapshot) -> Sequence[Event]: ...          # runner commits ONE event, then re-polls
    async def resolve(self, intent: OrderIntent, now: Block) -> tuple[Resolution, Sequence[Event]]: ...   # settle SUBMITTING/UNKNOWN from truth
    def observe(self, ev: Event) -> None: ...                                     # called for EVERY journaled event, also during recovery
    def mark_to(self, snap: ChainSnapshot) -> ChainSnapshot: ...                  # SIM/PAPER: add own-impact overlay; LIVE: identity

@dataclass(frozen=True, slots=True)
class Triggers: every_blocks: int | None; on_events: frozenset[str]              # cadence and/or Event.KIND wake-ups

@dataclass(frozen=True, slots=True)
class TickContext:
    now: LogicalTime; snapshot: ChainSnapshot
    events: tuple[Event, ...]          # derived chain events of THIS tick
    portfolio: Portfolio
    store: SnapshotStore               # bounded history; cannot see beyond `now`

class Strategy(Protocol):
    id: StrategyId; triggers: Triggers; warmup_blocks: int
    def on_tick(self, ctx: TickContext) -> Sequence[Signal]: ...                  # deterministic: no clock, I/O, randomness, unsorted sets
    def dump_state(self) -> bytes: ...                                            # checkpoints only; recovery can always rebuild by replay
    def load_state(self, blob: bytes) -> None: ...

@dataclass(frozen=True, slots=True)
class RiskContext: tick: TickContext; nav_rao: int; halted_entries: bool

@runtime_checkable
class RiskOverlay(Protocol):
    name: str
    def review(self, proposal: TargetWeights, ctx: RiskContext) -> RiskDecision: ...   # monotone: lower targets / forced exits / veto / halt

@dataclass(frozen=True, slots=True)
class EventRecord:
    seq: int; batch: int; time: LogicalTime; kind: str; payload: bytes; idem: str | None; prev_hash: bytes; hash: bytes

class Journal(Protocol):
    def append_batch(self, items: Sequence[tuple[LogicalTime, Event]]) -> list[EventRecord]: ...   # ATOMIC + DURABLE or raises, nothing written
    def read(self, from_seq: int = 1) -> list[EventRecord]: ...
    def has_idem(self, key: str) -> bool: ...
    def head(self) -> tuple[int, bytes]: ...
    def verify_chain(self) -> int: ...
```
Design notes. (1) `SnapshotObserved` carries only (block, hash, digest); the 128-subnet payload lives in the lake, so a backtest journal stays small and a live journal never duplicates market data. (2) `Signal.weight_ppm` is the float-to-integer firewall: everything downstream (allocation, caps, sizing, limit prices) is integer or Decimal. (3) `Position.shares` is exact `Decimal`; value in alpha is always `HotkeyPool.value_of(shares)`, which is how yield accrues without any trade. (4) The typed `Portfolio` and the double-entry `Ledger` are updated independently from the same events and cross-checked by `check_invariants` after every commit; a breach means halt plus alert, never a crash loop.
